public static AAXGeneralJournalPostedBusinessEventContract newFromLedgerJournalTable(LedgerJournalTable _ledgerJournalTable)
{
    var contract = new AAXGeneralJournalPostedBusinessEventContract();
    contract.initialize(_ledgerJournalTable);

    return contract;
}

